  final List<List<int>> graph = [
    [1, 2], 
    [1, 3], 
    [4, 2], 
    [2, 4], 
    [2, 3], 
    [3, 1], 
    [3, 4]
  ];

  final int n = graph.length;
  final List<bool> visited = List<bool>.filled(n, false);
  final List<int> topologicalSort(List<List<int>> graph, int n) {
    final List<int> sorted = <int>[];
    final List<int> stack = <int>[];
    final List<int> result = <int>[];

    for (int i = 0; i < n; i++) {
      if (!visited[i]) {
        visited[i] = true;
        stack.add(i);
      }
    }

    while (stack.isNotEmpty) {
      final int current = stack.removeLast();
      sorted.add(current);

      for (final int neighbor in graph[current]) {
        if (!visited[neighbor]) {
          visited[neighbor] = true;
          stack.add(neighbor);
        }
      }
    }

    return sorted;
  }

  if (topologicalSort(graph, n).isEmpty) {
    print('Graph contains a cycle, topological sort not possible.');
  } else {
    print('Topological Sort: ${topologicalSort(graph, n).join(' -> ')}');
  }
}

