  Set<int> result = {};
  for (String track in playlists) {
    if (track.isEmpty) {
      continue;
    }
    int colon = track.lastIndexOf(':');
    if (colon == -1) {
      continue;
    }
    String durationStr = track.substring(colon + 1);
    if (durationStr.isEmpty) {
      continue;
    }
    int? minutes;
    int? seconds;
    for (String part in durationStr.split(',')) {
      if (part.isEmpty) {
        continue;
      }
      int split = part.indexOf(':');
      if (split != 2) {
        continue;
      }
      String minutesStr = part.substring(0, split);
      String secondsStr = part.substring(split + 1);
      if (minutesStr.isEmpty) {
        continue;
      }
      if (secondsStr.isEmpty) {
        continue;
      }
      minutes = int.tryParse(minutesStr);
      seconds = int.tryParse(secondsStr);
    }
    if (minutes == null || seconds == null) {
      continue;
    }
    if (minutes < 0 || minutes > 59 || seconds < 0 || seconds > 59) {
      continue;
    }
    result.add(minutes * 60 + seconds);
  }
  return result;
}

