bool wordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[s.length];
}

List<String> minWordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<int> dp = List.filled(s.length + 1, s.length + 1);
  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] != s.length + 1 && wordSet.contains(s.substring(j, i))) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }

  List<String> result = [];
  int len = s.length;
  int prev = dp[len];
  List<String> path = [];

  while (prev > 0) {
    path.add(s.substring(prev - 1, prev));
    prev = dp[prev - 1];
  }

  int idx = 0;
  while (idx < path.length) {
    if (path[idx] != s.substring(idx, idx + 1)) {
      idx++;
    } else {
      int start = idx;
      while (idx < path.length && path[idx] == s.substring(idx, idx + 1)) {
        idx++;
      }
      result.add(path.sublist(start, idx));
      idx++;
    }
  }

  return result;
}

List<List<String>> wordBreakAll(String s, List<String> wordDict) {
