    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  void backtrack(int idx, List<String> path) {
    if (idx == s.length) {
      result.add(List<String>.from(path));
      return;
    }

    for (int j = idx; j < s.length; j++) {
      if (dp[j] && wordSet.contains(s.substring(idx, j + 1))) {
        path.add(s.substring(idx, j + 1));
        backtrack(j + 1, path);
        path.removeLast();
      }
    }
  }

  backtrack(0, []);
  return result;
}

