      List<String> ways = memo[current + word[i]]!;
      for (String way in ways) {
        backtrack(i + 1, current + word[i] + way);
      }
    }
  }

  for (int i = 0; i < word.length; i++) {
    backtrack(i, "");
  }
  return result;
