      final key = path[0];
      if (!root.containsKey(key)) {
        root[key] = 0;
      }
      final count = int.parse(path[1]);
      root[key] = (root[key] ?? 0) + count;
    }
    history.add(stack.length.toString());
  }
  final total = <String, dynamic>{};
  for (final s in stack) {
    total.addAll(s);
  }
  final sorted = total.entries.toList();
  sorted.sort((a, b) {
    final c = b.value.compareTo(a.value);
    if (c != 0) {
      return c;
    }
