    print('First argument must be an integer k (size of combinations). Got: ${args.first}');
    print('Second argument must be a list of items. Got: ${args.last}');
    return;
  }

  final int k = int.tryParse(args[0]) ?? 0;
  final List<String> items = args[1].split(' ');

  if (k <= 0 || k > items.length) {
    print('k must be between 0 and n (inclusive). n=${items.length}, k=$k');
