  List<String> current = <String>[];

  void backtrack(int start, int remaining) {
    if (remaining == 0) {
      combinations.add(List.from(current));
      return;
    }

    for (int i = start; i < items.length; i++) {
      current.add(items[i]);
      backtrack(i + 1, remaining - 1);
      current.removeLast();
    }
  }

  backtrack(0, k);

  for (final combination in combinations) {
    print(combination);
  }
}

