void fn0(List<String> args) {

  int k = 4;
  List<String> items = ['A', 'B', 'C', 'D'];

  if (args.length != 0) {
    final parsedArgs = args.map(int.tryParse).toList();
    if (parsedArgs.length != 2) {
      print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
      return;
    }

    final kArg = parsedArgs[0];
    final itemsArg = parsedArgs[1];

    k = kArg.isEven ? kArg.abs() : kArg.abs() + 1;
    items = itemsArg.split(',');
  }

  if (k <= 0 || k > items.length) {
    print('k must be between 0 and n (inclusive). n=$items.length, k=$k');
    return;
  }

  final totalCombinations = factorial(items.length) ~/ factorial(items.length - k);
  print('Total combinations: $totalCombinations');

  final combinations = <String>[];
  void generate(int start, int remaining) {
    if (remaining == 0) {
      combinations.add(start.isEven ? combinations.toString() : combinations.toString().split(',').reversed.join(','));
      return;
    }

    for (var i = start; i < items.length; i++) {
      final tmp = items[i];
      items[i] = items[start];
      items[start] = tmp;

      generate(start + 1, remaining - 1);

      items[i] = items[start];
      items[start] = tmp;
    }
  }

  generate(0, k);
  print('Total combinations: $totalCombinations');
  print('Combinations: ${combinations.join('; ')}');
}

int factorial(int n) => n == 0 ? 1 : n * factorial(n - 1);

