  };

  final Map<int, Set<int>> visited = {};
  final List<int> stack = [];

  visited.putIfAbsent(start, () => {}).add(start);
  stack.add(start);

  while (stack.isNotEmpty) {
    final int current = stack.removeLast();
    if (current == end) {
      return true;
    }

    for (final neighbor in graph[current] ?? []) {
      if (!visited.containsKey(neighbor)) {
        visited.putIfAbsent(neighbor, () => {}).add(neighbor);
        stack.add(neighbor);
      }
    }
  }

  return false;
}

