    }
  }
  uniq.sort();
  for (var len in uniq) {
    List<String> list = [];
    for (var e in valid) {
      if (e.length == len) list.add(e);
    }
    int minLen = list.length;
    int maxLen = list.length;
    for (int i = 1; i < list.length; i++) {
      int lenA = list[i - 1].length;
      int lenB = list[i].length;
      int diffA = lenA - lenB.abs();
      int diffB = lenB - lenA.abs();
      if (diffA > diffB) {
        minLen = lenA;
        maxLen = lenB;
      } else if (diffA < diffB) {
        minLen = lenB;
        maxLen = lenA;
      } else {
        if (lenA > lenB) {
          minLen = lenA;
          maxLen = lenB;
        } else if (lenB > lenA) {
          minLen = lenB;
          maxLen = lenA;
        } else {
          if (list[i - 1].compareTo(list[i]) < 0) {
            minLen = lenA;
            maxLen = lenB;
          } else {
            minLen = lenB;
            maxLen = lenA;
          }
        }
      }
    }
    for (int d = minLen; d <= maxLen; d++) {
      List<String> subset = [];
      for (var e in list) {
        if (e.length == d) subset.add(e);
      }
      if (subset.isEmpty) continue;
      int hashVal = 0;
      for (int i = 0; i < subset.length; i++) {
        hashVal += subset[i].codeUnitAt(0) * (i + 1);
      }
      if (result.contains(hashVal)) continue;
      result.add(hashVal);
    }
  }
  return result;
}

