List<int> fn0(List<String> events) {
  Set<int> visited = {};
  List<int> stack = [];
  for (var event in events) {
    if (event == '!') {
      if (stack.isNotEmpty) {
        visited.remove(stack.removeLast());
      }
    } else if (event == '^') {
      if (stack.isNotEmpty) {
        visited.remove(stack[stack.length - 1]);
      }
    } else if (event == '(') {
      stack.add(0);
    } else if (event == ')') {
      stack.add(1);
    } else if (event.isNotEmpty) {
      int idx = event.indexOf('#');
      int strength = int.parse(event.substring(idx + 1));
      visited.add(int.parse(event.substring(0, idx)));
      stack.add(strength);
    }
  }
  if (stack.isEmpty) return [];
  List<int> result = [];
  Set<int> seen = {};
  for (var v in stack) {
    if (!seen.add(v)) continue;
    result.add(v);
  }
  result.sort();
  return result;
}

