class Quaternion {

  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
        x * other.x - y * other.y - z * other.z - w * other.w,
        x * other.y + y * other.x + z * other.w - w * other.z,
        x * other.z + y * other.w + z * other.x - w * other.y,
        x * other.w + y * other.z + z * other.y - w * other.x,
      );

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  double norm() => x * x + y * y + z * z + w * w;

  Quaternion inverse() {
    final norm = norm();
    if (norm == 0) throw ArgumentError('Cannot invert zero quaternion');
    return Quaternion(
      x / norm,
      y / norm,
      z / norm,
      -w / norm,
    );
  }

  Quaternion normalized() {
    final norm = norm();
    if (norm == 0) throw ArgumentError('Cannot normalize zero quaternion');
    return Quaternion(
      x / norm,
      y / norm,
      z / norm,
      w / norm,
    );
  }

  bool get isUnit => norm() == 1;

  static Quaternion unit(double x, double y, double z, double w) =>
      Quaternion(x / sqrt(x * x + y * y + z * z + w * w), y / sqrt(x * x + y * y + z * z + w * w), z / sqrt(x * x + y * y + z * z + w * w), w / sqrt(x * x + y * y + z * z + w * w));

  static Quaternion fromEuler(double e1, double e2, double e3) =>
      Quaternion(
        cos(e1 / 2),
        sin(e1 / 2) * cos(e2 / 2),
        sin(e1 / 2) * sin(e2 / 2) * cos(e3 / 2),
        sin(e1 / 2) * sin(e2 / 2) * sin(e3 / 2),
      );

  static Quaternion fromAngleAxis(double angle, double axisX, double axisY, double axisZ) {

    final cosHalf = cos(angle / 2);
    final sinHalf = sin(angle / 2);

    final x = axisX * sinHalf;
    final y = axisY * sinHalf;
    final z = axisZ * sinHalf;
    final w = cosHalf;

    return Quaternion(x * x + y * y + z * z + w * w, x * y + y * z + z * x, x * z + y * w + z * w, x * w + y * z + z * y);
  }

  @override
  String toString() => 'Quaternion($x, $y, $z, $w)';
}

