/// Represents a quaternion in homogeneous coordinates.
/// A quaternion consists of a scalar part (w) and a vector part (v)
/// where v has an absolute value of 1.
class Quaternion {
  final double w;
  final double x, y, z;

  const Quaternion(this.w, [this.x = 0.0, this.y = 0.0, this.z = 0.0]);

  /// Creates a quaternion from a double value.
  factory Quaternion(double value) => Quaternion(value, 0.0, 0.0, 0.0);

  /// Creates a quaternion from a 3-element list.
  factory Quaternion.fromList(List<double> parts) {
    return Quaternion(parts[0], parts[1], parts[2], parts[3]);
  }

  /// Computes the conjugate of the quaternion.
  Quaternion get conjugate => Quaternion(w, -x, -y, -z);

  /// Computes the inverse of the quaternion.
  Quaternion get inverse => Quaternion(w, x / (w * w), y / (w * w), z / (w * w));

  /// Computes the squared norm of the quaternion.
  double get norm => w * w + x * x + y * y + z * z;

  /// Normalizes the quaternion so that the norm is 1.
  Quaternion get normalized => Quaternion(
    w / norm,
    x / norm,
    y / norm,
    z / norm,
  );

  /// Performs addition with another quaternion.
  Quaternion operator +(Quaternion other) => Quaternion(
        w + other.w,
        x + other.x,
        y + other.y,
        z + other.z,
      );

  /// Performs subtraction with another quaternion.
  Quaternion operator -(Quaternion other) => Quaternion(
        w - other.w,
        x - other.x,
        y - other.y,
        z - other.z,
      );

  /// Performs multiplication with a scalar.
  Quaternion operator *(double factor) => Quaternion(w * factor, x * factor, y * factor, z * factor);

  /// Performs multiplication with another quaternion.
  Quaternion operator *(Quaternion other) =>
      Quaternion(
        w * other.w - x * other.x - y * other.y - z * other.z,
        w * other.x + x * other.w + y * other.z - z * other.y,
        w * other.y + y * other.w + z * other.x - x * other.z,
        w * other.z + z * other.w + x * other.y - y * other.x,
      );

  @override
  String toString() {
    return 'Quaternion($w, $x, $y, $z)';
  }
}

