/// Quaternion class implementing basic arithmetic operations.
class Quaternion {
  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
          x * other.w + other.x * w,
          y * other.w + other.y * w,
          z * other.w + other.z * w,
          x * other.w * w + y * other.w * w + z * other.w * w);

  double norm() => x * x + y * y + z * z + w * w;

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() =>
      Quaternion((x * x + y * y + z * z + w * w).sqrtToDouble(),
          -x / (x * x + y * y + z * z + w * w),
          -y / (x * x + y * y + z * z + w * w),
          -z / (x * x + y * y + z * z + w * w));

  Quaternion normalized() {
    final double n = norm();
    if (n == 0) return Quaternion(0, 0, 0, 0);
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  @override
  String toString() =>
      'Quaternion($x, $y, $z, $w)';
}

