class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  Quaternion operator *(Quaternion other) {

    double xx = x * x;
    double yy = y * y;
    double zz = z * z;

    double x2 = x * 2;
    double y2 = y * 2;
    double z2 = z * 2;

    return Quaternion(
      xx * other.w - x2 * other.z,
      yy * other.w - y2 * other.z,
      zz * other.w - z2 * other.z,
      xx * other.w + yy * other.w + zz * other.w,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      scalar * x,
      scalar * y,
      scalar * z,
      scalar * w,
    );
  }

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  Quaternion normalized() {
    double n = norm();
    if (n == 0) return Quaternion(0.0, 0.0, 0.0, 0.0);
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion conjugate() {
    return Quaternion(x, -y, -z, w);
  }

  Quaternion inverse() {
    double n = norm();
    if (n == 0) return Quaternion(0.0, 0.0, 0.0, 0.0);
    return Quaternion(
      x / n,
      -y / n,
      -z / n,
      w / n,
    );
  }

