/// A Quaternion class representing a unit quaternion in 3D space.
/// A Quaternion consists of a scalar part (real) and a vector part (3 doubles).
/// A Quaternion always represents a rotation around a unit axis (length 1).
class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  /// The norm of a Quaternion, also known as its magnitude.
  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  /// The conjugate of a Quaternion.
  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  /// The inverse of a Quaternion.
  Quaternion inverse() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(
      x / n,
      y / n,
      z / n,
      w / n,
    );
  }

  /// The complex conjugate of a Quaternion.
  Quaternion complex() {
    return Quaternion(x, y, z, w);
  }

  /// The normalized version of this Quaternion.
  /// A Quaternion is normalized if its norm is 1.
  /// A Quaternion is always represented as a unit quaternion (length 1).
  Quaternion normalized() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(
      x / n,
      y / n,
      z / n,
      w / n,
    );
  }

  /// The real part of the Quaternion.
  double get real => w;

  /// The imaginary part of the Quaternion.
  double get imaginary => sqrt(x * x + y * y + z * z);

  /// The vector part of the Quaternion.
  Vector3 get vector => Vector3(x, y, z);

  /// Addition of two Quaternions.
  /// Quaternion addition is performed component-wise.
  /// The real parts are added separately.
  /// The vector parts are added separately.
  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  /// Subtraction of two Quaternions.
  /// Quaternion subtraction is performed component-wise.
  /// The real parts are subtracted separately.
  /// The vector parts are subtracted separately.
  Quaternion operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  /// Multiplication of two Quaternions.
  /// Quaternion multiplication is performed using the following formula:
  /// q1 * q2 = q1_real * q2_real - q1_imag * q2_imag
  ///          + q1_real * q2_imag - q1_imag * q2_real
  /// The real parts are multiplied separately.
  /// The imaginary parts are multiplied separately.
  /// The complex conjugates are multiplied separately.
  /// The results are combined using the formulas above.
  Quaternion operator *(Quaternion other) {
    double q1r = x;
    double q1i = y * i;
    double q2r = other.x;
    double q2i = other.y * i;
    double q12r = q1r * q2r - q1i * q2i;
    double q12i = q1r * q2i + q1i * q2r;
    return Quaternion(q12r, q12i, z * other.z, w * other.w);
  }

  /// Scalar multiplication of a Quaternion by a double.
  /// The scalar part is multiplied separately.
  /// The vector part is scaled by the scalar.
  Quaternion operator *(double scalar) {
    return Quaternion(
      x * scalar,
      y * scalar,
      z * scalar,
      w * scalar,
    );
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

