Ray rotate(Ray ray, double theta, Vector3 axis) {
  final e = axis.normalized();
  final axisPerp = Vector3(0.0, 0.0, 1.0).cross(e);
  return ray +
      (e * theta * ray.direction +
          axisPerp * theta * dot(ray.direction, axisPerp));
}

