  int bracketSize = 1;
  for (int i = 0; i < input.length; i++) {
    String c = input[i];
    if (c == 'P') {
      stack.add(bracketSize);
      bracketSize *= 2;
    } else if (c == 'M') {
      if (stack.isEmpty) return 0.0;
      int last = stack.removeLast();
      bracketSize = last;
    } else if (c == 'D') {
      if (stack.isEmpty) return 0.0;
      stack.add(bracketSize);
      bracketSize ~/= 2;
    } else if (c == 'S') {
      if (stack.length < 2) return 0.0;
      int b2 = stack.removeLast();
      int b1 = stack.removeLast();
      bracketSize = b1;
      stack.add(b2);
    } else if (c == 'R') {
      if (stack.length < 2) return 0.0;
      int b2 = stack.removeLast();
      int b1 = stack.removeLast();
      stack.addAll(List.filled(2, b1));
    } else if (c.codeUnitAt(0) >= 65 && c.codeUnitAt(0) <= 90) {
      stack.add(bracketSize);
      bracketSize *= 2;
    } else if (c.codeUnitAt(0) >= 97 && c.codeUnitAt(0) <= 122) {
      stack.add(bracketSize);
      bracketSize ~/= 2;
    } else {
      return 0.0;
    }
  }
  if (stack.isEmpty) return 0.0;
  int total = 0;
  for (int v in stack) {
    total += v;
  }
  return total / 2.0;
}

