Map<String, int> fn0(List<int> moistureGrid, int threshold) {
  if (moistureGrid.isEmpty || threshold < 0) return {};
  int rows = moistureGrid.length;
  int cols = moistureGrid[0].length;
  if (cols == 0) return {};
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      int val = moistureGrid[i][j];
      if (val < 0) {
        dp[i][j] = -1;
        continue;
      }
      int best = val;
      if (i > 0) {
        int neighbor = dp[i - 1][j];
        if (neighbor >= 0 && neighbor > best) best = neighbor;
      }
      if (j > 0) {
        int neighbor = dp[i][j - 1];
        if (neighbor >= 0 && neighbor > best) best = neighbor;
      }
      if (i > 0 && j > 0) {
        int neighbor = dp[i - 1][j - 1];
        if (neighbor >= 0 && neighbor > best) best = neighbor;
      }
      if (best != val) {
        dp[i][j] = best;
      } else {
        dp[i][j] = -1;
      }
    }
  }
  Map<String, int> result = {};
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (dp[i][j] >= 0 && dp[i][j] <= threshold) {
        String key = i.toString() + ',' + j.toString();
        result[key] = dp[i][j];
      }
    }
  }
  return result;
}

