Map<String, int> fn0(List<int> quantities, int threshold) {
  if (quantities.isEmpty) return {};
  int left = 0;
  int sum = 0;
  int bestStart = 0;
  int bestLen = 1;
  for (int right = 0; right < quantities.length; right++) {
    sum += quantities[right];
    while (sum >= threshold && left <= right) {
      int curLen = right - left + 1;
      if (curLen > bestLen) {
        bestLen = curLen;
        bestStart = left;
      }
      sum -= quantities[left];
      left++;
    }
  }
  if (bestLen == 0) return {};
  return {bestStart.toString(): bestLen};
}

