  int n = rounds.length;
  if (n == 1) return {rounds[0].toString(): 1};

  List<List<int>> dp = List.generate(n, (_) => List.filled(target + 1, 0));
  dp[0][0] = 1;

  for (int i = 0; i < n; i++) {
    for (int j = 0; j <= target; j++) {
      if (rounds[i] <= j) {
        dp[i][j] = dp[i - 1][j] + dp[i][j - rounds[i]];
      } else {
        dp[i][j] = dp[i - 1][j];
      }
    }
  }

  Map<String, int> result = {};
  for (int j = 0; j <= target; j++) {
    if (dp[n - 1][j] > 0) {
      result[j.toString()] = dp[n - 1][j];
    }
  }
  return result;
}

