int findPattern(String text, String pattern) {
  int n = text.length;
  int m = pattern.length;

  if (m == 0 || m > n) return -1;

  List<List<bool>> lps = List.generate(n + 1, (_) => List<bool>.filled(patternLength + 1, false));

  for (int i = 0; i <= n; i++) {
    lps[i][0] = true;
  }

  for (int j = 1; j <= patternLength; j++) {
    int k = 0;

    while (k < patternLength && pattern[j] == pattern[k]) {
      k++;
    }

    lps[0][j] = k == patternLength;
  }

  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= patternLength; j++) {

      if (pattern[j] == text[i]) {
        lps[i][j] = lps[i - 1][j - 1] + 1;
      } else {
        lps[i][j] = (lps[i - 1][j] != 0) ? lps[i - 1][j] : 0;
      }
    }
  }

  int k = 0;
  int m = 0;

  while (m < textLength) {
    if (pattern[k] == text[m]) {
      k++;
      m++;
    }

    if (k == patternLength) {
      return m - k;
    } else if (m < textLength && pattern[k] != text[m]) {
      if (k != 0) {
        k = lps[m][k - 1];
      } else {
        m++;
      }
    }
  }

  return -1;
}

