bool naiveKMP(String text, String pattern) {
  int m = text.length;
  int n = pattern.length;

  if (n > m) return false;
  if (n == 0) return true;

  for (int i = 0; i <= m - n; i++) {
    int j = 0;
    while (j < n && pattern[j] == text[i + j]) {
      j++;
    }
    if (j == n) return true;
  }

  return false;
}

