int fn0(List<int> bins, int k) {
  int n = bins.length;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    int a = bins[i] <= k ? 1 : 0;
    int b = (i > 0 && bins[i - 1] <= k) ? dp[i - 1] + 1 : 0;
    dp[i + 1] = a > b ? a : b;
  }
  return dp[n];
}

