void testUserResourceAccess(Map<String, User> users, Map<String, Resource> resources, {bool deny = false}) {

  for (var user in users.values) {
    for (var resource in resources.keys) {
      String action = deny ? 'DENIED' : 'SUCCESS';
      print('User "${user.name}": ${accessResource(users, resource, user, deny)}');
    }
  }
}

String accessResource(Map<String, User> users, String resource, User user, bool deny) {
  if (!users.containsKey(user.name)) {
    return '  ➜ User "${user.name}" not found';
  }

  String role = deny
      ? (users[user.name]!.roles.isEmpty
          ? 'DENIED'
          : (users[user.name]!.roles.first))
      : (users[user.name]!.roles.first);


  var roleDetails = roles[role];
  if (roleDetails == null) {
    return '  ➜ Role "${role}" not found';
  }

  var resourceDetails = resources[resource];
  if (resourceDetails == null) {
    return '  ➜ Resource "${resource}" not found';
  }

  String accessStatus = deny
      ? 'Access denied'
      : 'Access granted (Role: ${roleDetails.name})';

  return '  ➜ ${user.name} attempts to $access: ${resource} → $accessStatus';
}

void promoteRoleAndTest(Map<String, Role> roles, Map<String, User> users, Map<String, Resource> resources, String userName) {

  if (!roles.containsKey(userName)) {
    return;
  }

  String newRole = '${userName}_admin';
  Role newRoleDetails = Role(newRole, [
    'read',
    'write',
    'delete',
    'admin'
  ]);

  roles[newRole] = newRoleDetails;

  print('Elevating ${users[userName]!.name} to admin role...');
  print('New role for ${users[userName]!.name}: ${newRoleDetails.name}\n');

  testUserResourceAccess(users, resources, deny: true);
}

void inheritRolesAndTest(Map<String, Role> roles, Map<String, User> users, Map<String, Resource> resources) {

  for (var user in users.values) {
    for (var resource in resources.keys) {

      String parentRole = (resources[resource]!.accessMatrix)[user.roles.first];
      if (parentRole == null) {
        continue;
      }

      Role parentRoleDetails = roles[parentRole]!;

      String accessStatus = accessResource(users, resource, user, deny: false);
      print('  ➜ ${user.name} inherits ${parentRoleDetails.name}: ${accessStatus}');
    }
  }
}

