import 'dart:async';
import 'dart:convert';
enum UserRole { user, moderator, admin }

extension UserRoleExtension on UserRole {
  String get name {
    switch (this) {
      case UserRole.user:
        return 'User';
      case UserRole.moderator:
        return 'Moderator';
      case UserRole.admin:
        return 'Admin';
    }
  }

  bool get isSuperUser => this == UserRole.admin;
}

abstract class Resource {
  String get name;
  bool get isCritical => false; 
}

class Document extends Resource {
  final String name;
  Document(this.name);

  @override
  String get name => this.name;

  @override
  bool get isCritical => false; 
}

class Database extends Resource {
  final String name;
  Database(this.name);

  @override
  String get name => this.name;

  @override
  bool get isCritical => true; 
}

class Config extends Resource {
  final String name;
  Config(this.name);

  @override
  String get name => this.name;

  @override
  bool get isCritical => true; 
}

class AccessControl {
  final Map<UserRole, Map<Resource, Set<String>>> permissions = {
    UserRole.user: {
      Document('document1'): {'read'},
      Document('document2'): {'read'},
      Database('db1'): {'read'},
      Database('db2'): {'read'},
      Config('config1'): {'read'}
    },
    UserRole.moderator: {
      Document('document1'): {'read', 'write'},
      Document('document2'): {'read', 'write'},
      Database('db1'): {'read', 'write'},
      Database('db2'): {'read', 'write'},
      Config('config1'): {'read', 'write'}
    },
    UserRole.admin: {
      Document('document1'): {'read', 'write', 'delete'},
      Document('document2'): {'read', 'write', 'delete'},
      Database('db1'): {'read', 'write', 'delete'},
      Database('db2'): {'read', 'write', 'delete'},
      Config('config1'): {'read', 'write', 'delete'},
      Config('config2'): {'read', 'write', 'delete'}
    }
  };

  bool checkAccess(UserRole userRole, Resource resource, String action) {
    if (resource is! Resource) {
      return false;
    }

    if (userRole.isSuperUser) {
      return true;
    }

    if (!permissions[userRole]!.containsKey(resource)) {
      return false;
    }

    final allowedActions = permissions[userRole]![resource]!;
    if (!allowedActions.contains(action)) {
      return false;
    }

    return true;
  }
}

