void checkAccess(String user, String resource) {

  Map<String, List<String>> role = userPermissions[user] ?? {};
  String roleName = user.padRight(8) + ': ';

  for (var permission in resourcePermissions[resource] ?? []) {
    if (!role.contains(permission)) {
      print('  $roleName Access DENIED (${permission})');
    } else {
      print('  $roleName Access GRANTED (${permission})');
    }
  }
}

void promoteUserToRole(String user, String newRole) {
  Map<String, List<String>> roles = userPermissions[user] ?? {};
  String oldRole = user.padRight(8) + ': ';

  for (var permission in roles.removeWhere((perm) => perm.key == newRole).value) {
    roles[newRole] ??= [];
    roles[newRole]!.add(permission);
  }

  print('Elevating $oldRole to $newRole...');
  print('New role for $user: ${roles[newRole]}');
}

void logAccessAttempt(String user, String resource) {
  print('User $user attempts to access $resource');
}

