void testAccess(List<String> roles, List<String> resources, String action) {

  final result = <String>[];
  for (final role in roles) {
    final resource = resources.isNotEmpty ? resources[0] : '';

    final hasResource = resources.contains(resource);
    final hasAction = action == '*' || roles.contains(action);

    final access = hasResource && hasAction;
    final msg = access ? '  ➜ Access granted' : '  ➜ Access denied';

    result.add('$role -> $resource: $msg');
    resources.removeAt(0);
  }

  print('$action attempts to ${resources.isNotEmpty ? resources[0] : ''}: $result\n');
}

void elevateRole(Map<String, List<String>> users, String user, List<String> currentRoles, String newRole) {
  if (currentRoles.contains(newRole)) {
    print('  ➜ Role "$newRole" already exists');
  } else {
    users[user] = currentRoles + [newRole];
    print('  ➜ New role for "$user": "$newRole" added');
  }
}

