@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {


  final transactions = <List<String>>[
    ['Milk', 'Bread', 'Butter'],
    ['Bread', 'Butter'],
    ['Milk', 'Bread'],
    ['Milk', 'Butter'],
    ['Bread', 'Butter'],
    ['Milk']
  ];



  final minSupport = 0.5; 
  final minConfidence = 0.7; 

  final numTransactions = transactions.length;

  final itemSet = <Set<String>>[];
  for (final transaction in transactions) {

    for (final item in transaction) {
      itemSet.add({item});
    }
  }

  final candidateSet = <Set<String>>[];
  candidateSet.add({});

  while (candidateSet.isNotEmpty) {
    final current = candidateSet.removeLast();
    final superSets = <Set<String>>[];
    for (final item in current) {
      for (final other in itemSet) {
        if (other.containsAll(current) && other.length > current.length) {
          superSets.add(other);
        }
      }
    }
    candidateSet.addAll(superSets);
  }

  final supportCount = <String, int>{};
  for (final transaction in transactions) {
    for (final item in transaction) {
      supportCount[item] = (supportCount[item] ?? 0) + 1;
    }
  }

  final frequentItemsets = <Set<String>>[];
  for (final itemset in candidateSet) {
    final support = supportCount.entries
        .where((e) => itemset.contains(e.key))
        .length;
    if (support >= minSupport) {
      frequentItemsets.add(itemset);
    }
  }

  print('Frequent Itemsets:');
  for (final itemset in frequentItemsets) {
    print(itemset);
  }


  final rules = <List<String>>[];
  for (final itemset in frequentItemsets) {

    for (final item in itemset) {
      if (itemset.length > 1) {
        for (final other in frequentItemsets) {
          if (other.length == itemset.length - 1) {
            if (other.containsAll(itemset) && !other.contains(item)) {
              rules.add([item, other.toList()..remove(item)]);
            }
          }
        }
      }
    }
  }

  rules.sort((a, b) {
    final confidenceA = supportCount[b[1]]! / supportCount[a[1]]!;
    final confidenceB = supportCount[a[1]]! / supportCount[b[1]]!;
    if (confidenceA != confidenceB) {
      return confidenceB.compareTo(confidenceA);
    }
    return a[0].compareTo(b[0]);
  });

  print('\nAssociation Rules:');
  for (final rule in rules) {
    print('${rule[0]} -> ${rule[1]} (support: ${supportCount[rule[1]]}, confidence: ${supportCount[rule[1]]! / supportCount[rule[0]]!})');
  }
}

