void fn0() {

  Set<String> items = {'Milk', 'Bread', 'Butter'};
  List<List<String>> transactions = [
    ['Milk', 'Bread'],
    ['Milk', 'Bread', 'Butter'],
    ['Bread', 'Butter'],
    ['Milk', 'Bread'],
    ['Milk', 'Butter'],
    ['Bread', 'Butter'],
  ];

  Map<List<String>, int> itemFreq = {};
  for (var t in transactions) {
    for (var item in t) {
      itemFreq[item] = (itemFreq[item] ?? 0) + 1;
    }
  }

  List<List<String>> support(Map<List<String>, int> freq, double minSupport) {
    return freq.entries
        .where((e) => e.value >= minSupport * transactions.length)
        .map((e) => e.key)
        .toList();
  }

  double confidence(String antecedent, String consequent, Map<List<String>, int> freq) {
    if (freq.containsKey(antecedent) &&
        freq.containsKey(antecedent + consequent) &&
        freq[antecedent + consequent]! > 0) {
      return freq[antecedent]! / freq[antecedent + consequent]!;
    }
    return 0.0;
  }

  Map<List<String>, int> itemfreqWithSupport = {};
  for (var t in support(itemFreq, 0.5)) {
    itemfreqWithSupport[t] = itemFreq[t]!;
  }

  Set<List<String>> frequentItemsets = itemfreqWithSupport.keys.toSet();

  print('Frequent Itemsets:');
  for (var itemset in frequentItemsets) {
    print(itemset);
  }

  Map<String, int> freqOfItemsets = {};
  for (var t in frequentItemsets) {
    for (var item in t) {
      freqOfItemsets[item] = (freqOfItemsets[item] ?? 0) + 1;
    }
  }

  Map<List<String>, List<String>> assocRules = {};
  for (var itemset in frequentItemsets) {
    if (itemset.length > 1) {
      for (var i = 0; i < itemset.length - 1; i++) {
        String antecedent = itemset.sublist(0, i).join(' ');
        String consequent = itemset.sublist(i + 1).join(' ');
        if (confidence(antecedent, consequent, freqOfItemsets) >= 0.7) {
          assocRules[antecedent] = (assocRules[antecedent] ?? [])
              ..add(consequent);
        }
      }
    }
  }

  print('\nAssociation Rules:');
  for (var rule in assocRules.entries) {
    print('${rule.key} -> ${rule.value} (support: ${rule.value.length}, confidence: ${rule.key.isEmpty ? 0.0 : rule.value.length / rule.key.length})');
  }
}

