@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  Set<String> items = {'Milk', 'Bread', 'Butter'};

  int minSupport = 3; 

  int transactionsPerItem = 3; 

  Map<String, int> itemFrequency = {};

  List<Set<String>> transactions = [];

  for (int t = 0; t < transactionsPerItem; t++) {
    transactions.add(items.toSet());
  }

  for (int t = 0; t < transactionsPerItem; t++) {
    String item = items.toList()[t];
    itemFrequency[item] = 0;
  }

  for (int t = 0; t < transactions.length; t++) {
    Set<String> transaction = transactions[t];
    for (String item in transaction) {
      itemFrequency[item] = itemFrequency[item]! + 1;
    }
  }

  Set<String> frequentItems = {};
  for (var entry in itemFrequency.entries.where((e) => e.value >= minSupport).map((e) => e.key)) {
    frequentItems.add(entry);
  }

  List<List<String>> itemsets = [];
  itemsets.add(frequentItems.toList());

  while (true) {
    bool changed = false;
    for (int t = 0; t < transactions.length; t++) {
      Set<String> transaction = transactions[t];
      for (String item in transaction) {
        if (!frequentItems.contains(item)) {
          continue;
        }
        for (var itemset in itemsets) {
          if (itemset.contains(item)) {
            continue;
          }
          List<String> newItemset = List.from(itemset);
          newItemset.add(item);
          bool added = false;
          for (var existing in itemsets) {
            if (existing == newItemset) {
              added = true;
              break;
            }
          }
          if (!added) {
            itemsets.add(newItemset);
            changed = true;
          }
        }
      }
    }
    if (!changed) {
      break;
    }
  }

  print('Frequent Itemsets:');
  for (var itemset in itemsets) {
    print(itemset);
  }

  Map<String, int> supportCount = {};
  for (var itemset in itemsets) {
    for (String item in itemset) {
      supportCount[item] = (supportCount[item] ?? 0) + 1;
    }
  }

  print('\nAssociation Rules:');
  for (var entry in supportCount.entries.where((e) => e.value >= 2).map((e) => e.key)) {
    double confidence = (e.value / (transactions.length / 2)) * 100;
    print('"${e.key}" => "${e.key}'s support: ${e.value}, confidence: ${confidence.toStringAsFixed(1)}% (${e.value / (transactions.length / 2)})');
  }
}

