  for (var entry in transactions.entries) {
    String item = entry.key;
    int count = entry.value;

    if (count >= minSupport) {
      Set<String> itemset = {item};
      itemsets[itemset] = (itemsets[itemset] ?? 0) + 1;
    }

    for (int i = 2; i <= count; i++) {
      Set<String> kItems = itemset.toSet()..add(item);
      itemsets[kItems] = (itemsets[kItems] ?? 0) + 1;
    }
  }

  print('Frequent Itemsets:');
  for (var entry in itemsets.entries) {
    print('${entry.key} (support: ${entry.value})');
  }

  double confidenceThreshold = 0.7;
  List<List<String>> rules = [];

  for (var entry in itemsets.entries) {
    Set<String> itemset = entry.key;
    int support = entry.value;

    if (support < minSupport) {
      continue;
    }

    int n = itemset.length;
    List<Set<String>> subsets = [itemset];

    for (int i = 2; i <= n; i++) {
      Set<String> current = itemset.toSet();
      Set<String> prev = subsets.last.toSet();

      for (var item in current.difference(prev)) {
        Set<String> newSub = prev.toSet()..add(item);
        subsets.add(newSub);
      }
    }

    for (var subset in subsets) {
      if (subset.length != 2) {
        continue;
      }

      String antecedent = subset.toList().join('>');
      String consequent = itemset.difference(subset).toList().join('>');

      double confidence = support / (itemsets[itemset] ?? 0);
      if (confidence > confidenceThreshold) {
        rules.add([antecedent, consequent, confidence]);
      }
    }
  }

