    double ca = a[2] as double;
    double cb = b[2] as double;
    int cmp = cb.compareTo(ca);
    if (cmp != 0) {
      return cmp;
    }

    cmp = a[0].compareTo(b[0]);
    if (cmp != 0) {
      return cmp;
    }

    return a[1].compareTo(b[1]);
  });

  print('\nAssociation Rules:');
  for (var rule in rules) {
    print('${rule[0]} => ${rule[1]} (confidence: ${rule[2]})');
  }
}

