  final List<int> topScores = List<int>.filled(n, 0);
  final List<int> bottomScores = List<int>.filled(n, 0);

  int countDry(List<List<int>> grid, int row) {
    int dry = 0;
    for (int col = 0; col < grid[row].length; col++) {
      if (grid[row][col] == 0) dry++;
    }
