    for (int col = 0; col < grid[row].length; col++) {
      if (grid[row][col] == 1) wet++;
    }
    return wet;
  }

  for (int row = 0; row < n; row++) {
    final int dryCount = countDry(grid, row);
    final int wetCount = countWet(grid, row);
    final int priority = dryCount + reviewInterval * wetCount;

    topScores[row] = priority;
    bottomScores[row] = -priority;
  }

  int sumTop = 0;
  int sumBottom = 0;

  for (int i = 0; i < n; i++) {
    sumTop += topScores[i];
    sumBottom += bottomScores[i];
  }

  final int lowestPriorityIndex = sumTop <= sumBottom
      ? List<int>.generate(n, (i) => i).first
      : List<int>.generate(n, (i) => i).last;

  final int highestPriorityIndex = sumTop <= sumBottom
      ? List<int>.generate(n, (i) => i).last
      : List<int>.generate(n, (i) => i).first;

  return {
    'total': n,
    'dryCells': countDry(grid, 0),
    'rowsNeedingReview': n - 1,
    'lowestPriorityRow': lowestPriorityIndex,
    'highestPriorityRow': highestPriorityIndex,
  };
}

