  String toString() => 'Point($x, $y)';
}

class Rectangle {
  final double x1;
  final double y1;
  final double x2;
  final double y2;

  Rectangle(this.x1, this.y1, this.x2, this.y2);

  Rectangle.square(double centerX, double centerY, double halfWidth, double halfHeight)
      : this(centerX - halfWidth, centerY - halfHeight, centerX + halfWidth, centerY + halfHeight);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(p1.x, p1.y, p2.x, p2.y);

  Rectangle get bounds => Rectangle.square(x1, y1, x2 - x1, y2 - y1);

  bool contains(Point p) =>
      p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2;

  bool contains(Rectangle other) =>
      other.contains(Point(x1, y1)) && other.contains(Point(x2, y1)) &&
      other.contains(Point(x1, y2)) && other.contains(Point(x2, y2));

  bool overlaps(Rectangle other) =>
      !other.contains(Rectangle.fromPoints(Point(x1, y1), Point(x2, y2)));

  Rectangle union(Rectangle other) {
    return Rectangle.fromPoints(
      Point(x1, y1),
      other.contains(Point(x1, y1)) ? Point(x1, y1) : other.bounds.points[0],
    )
        ..union(Rectangle.fromPoints(
      Point(x2, y1),
      other.contains(Point(x2, y1)) ? Point(x2, y1) : other.bounds.points[1],
    ))
        ..union(Rectangle.fromPoints(
      Point(x1, y2),
      other.contains(Point(x1, y2)) ? Point(x1, y2) : other.bounds.points[2],
    ))
        ..union(Rectangle.fromPoints(
      Point(x2, y2),
      other.contains(Point(x2, y2)) ? Point(x2, y2) : other.bounds.points[3],
    ));
  }

  Rectangle subtract(Rectangle other) {
    return Rectangle.square(
      other.x1,
      other.y1,
      other.x2,
      other.y2,
    )
        .subtract(Rectangle.square(x1, y1, x2, y2));
  }

  Rectangle translate(double dx, double dy) {
    return Rectangle.square(x1 + dx, y1 + dy, x2 + dx, y2 + dy);
  }

  Rectangle scale(double sx, double sy) {
    return Rectangle.square(sx * x1, sy * y1, sx * x2, sy * y2);
  }

  List<Point> points = [];

  Rectangle get pointsRect => Rectangle.fromPoints(points[0], points[1]);
}

