    [3.5, 3.5],
    [5.0, 4.5],
  ];

  final numClusters = 4;

  final points = List<List<double>>.from(data);

  double euclideanDistance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  List<double> clusterCentroids(List<double> points) {
    if (points.isEmpty) {
      return <double>[];
    }
    if (points.length == 1) {
      return points[0];
    }
    final mid = points.length ~/ 2;
    final left  = clusterCentroids(points.sublist(0, mid));
    final right = clusterCentroids(points.sublist(mid));
    return <double>[
      (left[0] + right[0]) / 2.0,
      (left[1] + right[1]) / 2.0,
    ];
  }

  List<int> assignments = List.filled(points.length, -1);

  double distanceToCentroids(List<double> point) {
    double minDist = double.infinity;
    for (int i = 0; i < numClusters; i++) {
      final dist = euclideanDistance(point, clusterCentroids(points[i]));
      if (dist < minDist) {
        minDist = dist;
      }
    }
    return minDist;
  }

  for (int iter = 0; iter < 100; iter++) {

    final newAssignments = List<int>.generate(points.length, (i) => -1);

    for (int i = 0; i < points.length; i++) {
      final minDist = double.infinity;
      int bestCluster = -1;
      for (int j = 0; j < numClusters; j++) {
        final dist = distanceToCentroids(points[j]);
        if (dist < minDist) {
          minDist = dist;
          bestCluster = j;
        }
      }
      newAssignments[i] = bestCluster;
    }

    int numClustersChanged = 0;
    for (int i = 0; i < points.length; i++) {
      if (newAssignments[i] != assignments[i]) {
        numClustersChanged++;
        assignments[i] = newAssignments[i];
      }
    }
    if (numClustersChanged == 0) {
      print('Converged in ${iter + 1} iteration(s).');
      break;
    }
  }

  for (int i = 0; i < points.length; i++) {
    print('Cluster ${newAssignments[i] + 1}: ${points[i]}');
  }
}

