        int left = j - 1;
        int right = j + 1;
        int top = i - 1;
        int bottom = i + 1;

        if (left < 0) {
          left = 0;
        }
        if (right >= row.length) {
          right = row.length - 1;
        }
        if (top < 0) {
          top = 0;
        }
        if (bottom >= grid.length) {
          bottom = grid.length - 1;
        }

