        for (int k = left; k <= right; k++) {
          for (int l = top; l <= bottom; l++) {
            if (grid[l][k] == 1) {
              passingNeighbors++;
            }
          }
        }

        int score = row.length - passingNeighbors;
        if (score > maxScore) {
          maxScore = score;
        }
        if (row.length - passingNeighbors < shortest) {
          shortest = row.length - passingNeighbors;
        }
        if (row.length > longest) {
          longest = row.length;
        }
        segmentCount++;
      }
    }
